js=r'''
var G=[['p_light','k_light','Освещение'],['p_sock','k_sock','Розетки общего назначения'],
['p_pow','k_pow','Стационарные силовые приборы'],['p_heat','k_heat','Электроотопление и тёплые полы']];
function init(){$('faza').addEventListener('change',function(){$('u').value=S('faza')==='3'?'380':'220';});}
function calc(){
var u=P('u'),c=P('cos'),ko=P('ko'),tri=S('faza')==='3';
if([u,c,ko].some(isNaN))return err('Заполните напряжение, cos φ и коэффициент одновременности.');
if(u<=0)return err('Напряжение должно быть больше нуля.');
if(c<=0||c>1)return err('cos φ должен быть в диапазоне от 0 до 1.');
if(ko<=0||ko>1)return err('Коэффициент одновременности задаётся в диапазоне от 0 до 1.');
var pu=0,ps=0,h='';
for(var k=0;k<G.length;k++){
 if(S(G[k][0]).trim()==='')continue;
 var p=P(G[k][0]);
 if(isNaN(p))return err('Мощность группы «'+G[k][2]+'» должна быть числом — или оставьте поле пустым.');
 if(p<0)return err('Мощность группы не может быть отрицательной.');
 if(p===0)continue;
 var kc=P(G[k][1]);
 if(isNaN(kc)||kc<=0||kc>1)return err('Коэффициент спроса группы «'+G[k][2]+'» задаётся в диапазоне от 0 до 1.');
 pu+=p;ps+=kc*p;
 h+=row(G[k][2]+': '+fmt(p,5)+' кВт × '+fmt(kc,3),fmt(kc*p,5)+' кВт');
}
if(pu<=0)return err('Введите установленную мощность хотя бы одной группы.');
var pr=ko*ps,i=pr*1000/((tri?Math.sqrt(3):1)*u*c);
h+=row('Установленная мощность',fmt(pu,5)+' кВт')+
row('Сумма расчётных мощностей групп',fmt(ps,5)+' кВт')+
row('Расчётная мощность ввода Pр',fmt(pr,5)+' кВт')+
row('Итоговый коэффициент Pр / Pуст',fmt(pr/pu,4))+
row(tri?'Расчётный ток на фазу':'Расчётный ток',fmt(i,5)+' А');
if(S('p_razr').trim()!==''){
 var pa=P('p_razr');
 if(isNaN(pa))return err('Разрешённая мощность должна быть числом — или оставьте поле пустым.');
 if(pa<=0)return err('Разрешённая мощность должна быть больше нуля.');
 var over=pr-pa>1e-9*Math.max(1,pa);
 h+=row('Сравнение с разрешённой мощностью',over?'Превышает '+fmt(pa,5)+' кВт на '+fmt(pr-pa,4)+' кВт':'Не превышает '+fmt(pa,5)+' кВт');
}
h+=row('Статус выбора вводного автомата','Недостаточно данных')+
note((tri?'Ток указан на фазу при равномерном распределении нагрузки; перекос увеличит ток нагруженной фазы. ':'')+'Расчётная мощность и ток — исходные данные для проектировщика. Номинал вводного автомата должен удовлетворять IB ≤ In ≤ Iz для вводного кабеля, выдерживать ожидаемый ток КЗ, быть селективным с групповыми аппаратами и соответствовать техническим условиям на присоединение.');
out(h);
}
''',
about="""<div class="formula">Pр = Ко · Σ (Кс,i · Pуст,i)<br>I = Pр / (U · cos φ) — однофазный ввод<br>I = Pр / (√3 · U · cos φ) — трёхфазный, на фазу</div>
<p>Pуст,i — установленная мощность группы, то есть сумма паспортных мощностей её приёмников; Кс,i — коэффициент спроса группы: доля установленной мощности, которая участвует в общем максимуме; Ко — коэффициент одновременности максимумов разных групп.</p>
<p>Так устроен метод оценки максимальной нагрузки в Schneider Electric Electrical Installation Guide: к нагрузкам применяют коэффициент использования ku, к группам — коэффициент одновременности ks, и полученная максимальная мощность служит основой для выбора оборудования. Кс группы в этом калькуляторе соответствует произведению ku · ks для этой группы.</p>
<p>Источник прямо оговаривает, что коэффициенты одновременности определяет проектировщик: для этого нужно детальное знание установки и режимов работы цепей, поэтому точных значений для общего применения дать нельзя. В качестве ориентира там приведено: освещение — 1, отопление и кондиционирование — 1, розеточные цепи — 0,1–0,2, в отдельных случаях больше. В СП 256.1325800.2016 коэффициенты спроса тоже зависят от назначения здания, состава электроприёмников и заявленной мощности. Поэтому калькулятор ничего не подставляет сам и по умолчанию считает без снижения: Кс = 1 и Ко = 1 дают просто сумму установленных мощностей.</p>
<p><b>Снижение нельзя учитывать дважды.</b> Если Кс групп уже отражает, что группы не достигают максимума одновременно, Ко оставляют равным 1.</p>""",
example="""<p>Дом с однофазным вводом 220 В. Освещение 1 кВт (Кс = 1), розетки 8 кВт (Кс = 0,2 — принят по проекту), стационарные приборы 6 кВт (Кс = 0,5 — по проекту), электроотопления нет, Ко = 1, cos φ = 1. Расчётная мощность: 1 + 1,6 + 3 = <b>5,6 кВт</b> при установленной 15 кВт, расчётный ток — <b>25,45 А</b>. С теми же мощностями, но без снижения (все коэффициенты равны 1) получилось бы 15 кВт и 68,2 А: разница показывает, насколько результат зависит от обоснованности коэффициентов.</p>""",
