js=r'''
function calc(){
var p=P('p'),st=S('sost'),pwS=S('pw').trim(),puS=S('pu').trim();
var pw=pwS===''?null:P('pw'),pu=puS===''?null:P('pu');
if(isNaN(p))return err('Введите мощность нагрузки.');
if(p<=0)return err('Мощность нагрузки должна быть больше нуля.');
if(pw!==null&&(isNaN(pw)||pw<=0))return err('Мощность для смотанного кабеля должна быть положительным числом — или оставьте поле пустым.');
if(pu!==null&&(isNaN(pu)||pu<=0))return err('Мощность для размотанного кабеля должна быть положительным числом — или оставьте поле пустым.');
if(pw!==null&&pu!==null&&pw>pu)return err('По маркировке смотанный кабель не может выдерживать больше, чем размотанный: проверьте, не перепутаны ли значения.');
var h=row('Нагрузка',fmt(p,5)+' Вт');
if(pw!==null&&pu!==null)h+=row('Смотанный кабель по маркировке этой катушки',fmt(100*pw/pu,3)+' % от размотанного');
var lim=null,basis='';
if(st==='full'){
 if(pu!==null){lim=pu;basis='значение для размотанного кабеля';}
 else if(pw!==null&&p<=pw*(1+1e-9)){lim=pw;basis='значение для смотанного кабеля: размотанный выдерживает не меньше';}
}else if(pw!==null){
 lim=pw;basis=st==='part'?'значение для смотанного кабеля — частично смотанный оценивается как смотанный':'значение для смотанного кабеля';
}
if(lim===null){
 var why=st==='full'?'Для полностью размотанного кабеля нужна мощность с маркировки для размотанного состояния: значение для смотанного подтверждает только нагрузку не выше него.':'Для смотанного или частично смотанного кабеля нужна мощность с маркировки именно для смотанного состояния.';
 return out(h+row('Статус','Недостаточно данных')+
 note(why+' Пересчитывать одно значение в другое по «типовому проценту» нельзя: у моделей Brennenstuhl, IEK и RS PRO допустимая мощность смотанного кабеля составляет от 23 до 50 % мощности размотанного. Найдите значение на корпусе или в паспорте — ГОСТ 31223-2012 предусматривает маркировку обеих мощностей — либо полностью размотайте кабель.'));
}
var ok=p<=lim*(1+1e-9);
out(h+row('Применённый предел',fmt(lim,5)+' Вт — '+basis)+
row('Загрузка относительно предела',fmt(100*p/lim,4)+' %')+
row('Сравнение с маркировкой',ok?'Не превышает':'Превышает')+
row('Статус','Сравнение с маркировкой, не гарантия безопасности')+
note(ok?'Нагрузка не превышает значение маркировки для выбранного состояния кабеля. Маркировка относится к исправной катушке в обычных условиях: жара, солнце, укрытие катушки, повреждённая изоляция или ослабленные контакты уменьшают запас.':'Нагрузка превышает значение маркировки для выбранного состояния кабеля: кабель может нагреться выше допустимого изготовителем. Полностью размотайте кабель и сравните нагрузку с мощностью для размотанного состояния либо уменьшите нагрузку. Термозащита, если она есть, — аварийная мера, а не способ работать на пределе.'));
}
''',
about="""<p>Кабель нагревается током, а отдаёт тепло своей поверхностью. На барабане витки прижаты друг к другу, внутренние слои окружены такими же нагретыми витками, поэтому смотанный кабель при том же токе нагревается сильнее. Отсюда две мощности в маркировке: ГОСТ 31223-2012 (IEC 61242) предусматривает значение для полностью смотанного и для полностью размотанного кабеля.</p>
<div class="formula">Загрузка = Pнагрузки / Pмаркировки · 100 %<br>размотан полностью — предел Pразм; смотан или размотан частично — предел Pсмот</div>
<p>Универсального коэффициента снижения нет. По маркировке конкретных моделей смотанный кабель допускает очень разную долю мощности:</p>
<table class="t"><tr><th>Модель</th><th>Кабель</th><th>Смотан</th><th>Размотан</th><th>Доля</th></tr>
<tr><td>RS PRO, 15 м, 240 В</td><td>нет данных</td><td>720 Вт</td><td>3120 Вт</td><td>23 %</td></tr>
<tr><td>Brennenstuhl BAT 260, 40 м</td><td>H05VV-F 3G1,5</td><td>1000 Вт</td><td>3500 Вт</td><td>29 %</td></tr>
<tr><td>Brennenstuhl 320 KU 4200, 40 м</td><td>H07RN-F 3G2,5</td><td>1300 Вт</td><td>3300 Вт</td><td>39 %</td></tr>
<tr><td>IEK INDUSTRIAL УК20, 20 м</td><td>3 × 1,5 мм²</td><td>1750 Вт</td><td>3500 Вт</td><td>50 %</td></tr></table>
<p>Разброс — от 23 до 50 %. У моделей разные сечение, длина и конструкция барабана, и по маркировке не понять, что именно определяет разницу. Поэтому калькулятор не пересчитывает одну мощность в другую и при отсутствии нужного значения выдаёт «недостаточно данных».</p>
<p>Для частично смотанного кабеля стандарт отдельного значения не даёт. Оставшиеся на барабане витки по-прежнему охлаждаются плохо, а насколько меньше они нагреваются, чем при полной намотке, по маркировке не узнать. Поэтому калькулятор консервативно применяет предел для смотанного кабеля — это его допущение, а не требование стандарта.</p>""",
example="""<p>Катушка с маркировкой 1000 Вт для смотанного и 3500 Вт для размотанного кабеля, к ней подключён обогреватель 1500 Вт. Пока кабель на барабане, предел — 1000 Вт: загрузка <b>150 %</b>, маркировка превышена. Если размотать кабель полностью, предел — 3500 Вт, загрузка около <b>43 %</b>. Размотать «наполовину» недостаточно: для частично смотанного кабеля действует предел смотанного.</p>""",
