js=r'''
var NORM={
'gost-500':{u:500,r:1,doc:'ГОСТ Р 50571.16-2019, табл. 6.1',txt:'цепи до 500 В включительно'},
'gost-spd':{u:250,r:1,doc:'ГОСТ Р 50571.16-2019, п. 6.4.3.3',txt:'цепи до 500 В с неотключаемым УЗИП'},
'gost-selv':{u:250,r:0.5,doc:'ГОСТ Р 50571.16-2019, табл. 6.1',txt:'цепи БСНН или ЗСНН'},
'gost-1000':{u:1000,r:1,doc:'ГОСТ Р 50571.16-2019, табл. 6.1',txt:'цепи свыше 500 В'},
'pue':{u:1000,r:0.5,doc:'ПУЭ, табл. 1.8.34',txt:'электропроводки'}};
function calc(){
var n=NORM[S('norm')],ui=N(S('ui')),r=P('r');
if(!n)return err('Выберите документ и тип цепи.');
if(isNaN(r))return err('Введите показание мегаомметра числом.');
if(r<=0)return err('Показание должно быть больше нуля: нулевое означает замыкание или ошибку подключения, сравнивать с нормой нечего.');
var h=row('Документ',n.doc)+
row('Минимум для '+n.txt,fmt(n.r,3)+' МОм при '+n.u+' В')+
row('Показание',si(r*1e6,'Ом')+' при '+ui+' В');
if(ui!==n.u)return out(h+row('Испытательное напряжение',ui+' В вместо требуемых '+n.u+' В')+
 row('Статус','Недостаточно данных')+
 note('Минимум задан вместе с испытательным напряжением, и показание, снятое другим напряжением, с ним не сравнивается: при меньшем напряжении слабые места изоляции могут не проявиться, а большее может повредить подключённое оборудование. Повторите измерение напряжением '+n.u+' В или выберите документ, для которого ваше напряжение является требуемым.'));
var ok=r>=n.r*(1-1e-9);
out(h+row('Отношение показания к минимуму',fmt(r/n.r,4))+
row('Сравнение с минимумом',ok?'Не ниже минимума':'Ниже минимума')+
row('Статус',(ok?'Соответствует минимуму ':'Не соответствует минимуму ')+n.doc+' при данных условиях измерения')+
note(ok?'Показание не ниже минимума выбранного документа при этом испытательном напряжении. Это не вывод «изоляция в порядке»: сопротивление изоляции сильно зависит от температуры и влажности (эмпирическое правило Megger — примерно вдвое меньше на каждые 10 °C нагрева), от подготовки цепи и времени приложения напряжения. Для оценки состояния полезнее сравнение с прошлыми измерениями той же цепи в тех же условиях.':'Показание ниже минимума выбранного документа при данных условиях. Прежде чем искать повреждение, проверьте подготовку цепи: отключены ли электроприёмники, УЗИП и электронные устройства, нет ли влаги или конденсата. Если после этого показание остаётся ниже минимума, цепь не соответствует выбранной норме — нужен поиск места повреждения квалифицированным электриком.'));
}
''',
about="""<p>Мегаомметр подаёт постоянное испытательное напряжение между проводниками и измеряет ток через изоляцию, пересчитывая его в сопротивление. Нормативы задают минимум вместе с испытательным напряжением, и эти пары в разных документах различаются:</p>
<table class="t"><tr><th>Документ и цепь</th><th>Испытательное напряжение</th><th>Минимум</th></tr>
<tr><td>ГОСТ Р 50571.16-2019, БСНН и ЗСНН</td><td>250 В</td><td>0,5 МОм</td></tr>
<tr><td>ГОСТ Р 50571.16-2019, до 500 В включительно</td><td>500 В</td><td>1,0 МОм</td></tr>
<tr><td>ГОСТ Р 50571.16-2019, до 500 В с неотключаемым УЗИП</td><td>250 В</td><td>1,0 МОм</td></tr>
<tr><td>ГОСТ Р 50571.16-2019, свыше 500 В</td><td>1000 В</td><td>1,0 МОм</td></tr>
<tr><td>ПУЭ, табл. 1.8.34, электропроводки</td><td>1000 В</td><td>0,5 МОм</td></tr></table>
<div class="formula">сравнение возможно, только если Uисп = Uнорм<br>R ≥ Rmin — не ниже минимума;&nbsp;&nbsp;&nbsp;R &lt; Rmin — ниже минимума</div>
<p>ГОСТ Р 50571.16-2019 идентичен МЭК 60364-6:2016. Сопротивление считается удовлетворительным, если главный распределительный щит и каждая распределительная цепь, испытанная вместе с присоединёнными конечными цепями, но с отсоединёнными электроприёмниками, имеют сопротивление не меньше значения таблицы 6.1. УЗИП и оборудование, которое может исказить результат или повредиться, перед измерением отключают. Если УЗИП отключить практически невозможно — например, он встроен в стационарную розетку, — испытательное напряжение цепи допускается снизить до 250 В, но сопротивление должно быть не менее 1 МОм. ПУЭ в таблице 1.8.34 задаёт для приёмо-сдаточных испытаний электропроводок свою пару: 1000 В и 0,5 МОм. Какой документ применять, определяют проект и программа испытаний; калькулятор сравнивает с тем, который выбран.</p>
<p><b>Почему это не вердикт «изоляция в порядке».</b> Сопротивление изоляции сильно зависит от условий. Megger в руководстве «A Stitch in Time» приводит эмпирическое правило: на каждые 10 °C роста температуры сопротивление примерно вдвое падает, — и оговаривает, что у разных материалов эта зависимость своя. Если оборудование холоднее точки росы, конденсат на поверхностях заметно снижает показание. Калькулятор температурную поправку не вводит, а одно показание не заменяет сравнения с прошлыми измерениями той же цепи.</p>""",
example="""<p>Групповая линия 230 В проверена мегаомметром на 500 В, показание — 0,8 МОм. По ГОСТ Р 50571.16-2019 минимум для цепи до 500 В — 1,0 МОм при 500 В: показание <b>ниже минимума</b> при данных условиях. С таблицей ПУЭ ту же цифру сравнивать нельзя: для электропроводок там задано 1000 В, и калькулятор выдаст «недостаточно данных».</p>""",
