js=r'''
function sync(){var s=S('tip')==='svet';hideF('nl',!s);hideF('nr',!s);}
function init(){$('tip').addEventListener('change',sync);sync();}
function calc(){
var inom=N(S('inom')),u=P('u'),c=P('cos');
if(isNaN(u)||isNaN(c))return err('Введите напряжение и cos φ.');
if(u<=0)return err('Напряжение должно быть больше нуля.');
if(c<=0||c>1)return err('cos φ должен быть в диапазоне от 0 до 1.');
var ids=['p1','p2','p3','p4'],sum=0;
for(var k=0;k<ids.length;k++){
 if(S(ids[k]).trim()==='')continue;
 var v=P(ids[k]);
 if(isNaN(v))return err('Мощность прибора '+(k+1)+' должна быть числом — или оставьте поле пустым.');
 if(v<0)return err('Мощность прибора не может быть отрицательной.');
 sum+=v;
}
if(sum<=0)return err('Введите мощность хотя бы одного прибора.');
var ib=sum/(u*c),pmax=inom*u*c,ok=ib<=inom*(1+1e-9),d=pmax-sum;
if(Math.abs(d)<1e-6*Math.max(1,pmax))d=0;
var h=row('Суммарная одновременная мощность',fmt(sum,5)+' Вт')+
row('Расчётный ток IB',fmt(ib,4)+' А')+
row('Номинал автомата In',inom+' А')+
row('Загрузка от номинала',fmt(100*ib/inom,4)+' %')+
row('Условие IB ≤ In',ok?'Выполняется':'Не выполняется')+
row(ok?'Запас до номинала':'Превышение номинала',fmt(Math.abs(d),5)+' Вт');
var svet=S('tip')==='svet';
if(svet){
 var nl=P('nl'),nr=P('nr');
 if(isNaN(nl)||isNaN(nr))return err('Для линии освещения введите число ламп и розеток на фазу.');
 if(nl<0||nr<0||Math.floor(nl)!==nl||Math.floor(nr)!==nr)return err('Число ламп и розеток — целые неотрицательные числа.');
 var tot=nl+nr;
 h+=row('Ламп и розеток на фазу',tot+' шт.')+
 row('Ограничение ПУЭ 6.2.10',tot<=20?'Не более 20 — соблюдено':'Больше 20 — превышено ограничение, заданное «как правило»');
}
h+=row('Статус','Проверена одновременная нагрузка; кабель не проверялся')+
note((ok?'Проверено только условие IB ≤ In: одновременно включённые приборы не превышают номинал автомата. ':'Одновременно включённые приборы превышают номинал автомата: условие IB ≤ In не выполняется, группу нужно разделить или не включать эти приборы вместе. ')+'Автомат должен ещё защищать кабель группы — In ≤ Iz, это проверяет калькулятор выбора автомата. Номинал самих розеток, обычно 10 или 16 А, ограничивает нагрузку каждой из них.'+(svet?' Пункт 6.2.10 ПУЭ сформулирован «как правило» для ламп накаливания и разрядных ламп и содержит исключения; применение его к светодиодным светильникам — допущение.':''));
out(h);
}
''',
about="""<div class="formula">IB = ΣP / (U · cos φ)&nbsp;&nbsp;&nbsp;условие: IB ≤ In&nbsp;&nbsp;&nbsp;(полностью: IB ≤ In ≤ Iz)</div>
<p>ΣP — сумма мощностей приборов, которые могут работать одновременно, In — номинал автомата группы, Iz — допустимый длительный ток кабеля. Двойное условие IB ≤ In ≤ Iz установлено МЭК 60364-4-43, п. 433.1, в России — ГОСТ Р 50571.4.43-2012: расчётный ток не должен превышать номинал аппарата защиты, а номинал — допустимый ток кабеля. Этот калькулятор проверяет левую часть условия, правую — калькулятор выбора автомата.</p>
<p><b>Сколько розеток можно поставить на один автомат?</b> Предельного числа розеток для розеточной группы в ПУЭ и СП 256.1325800.2016 мы не нашли; СП, наоборот, задаёт минимальное оснащение помещений розетками. Группу ограничивает не число розеток, а то, что будет включено одновременно: десяток розеток под зарядные устройства и настольные лампы нагружает линию меньше, чем одна розетка под обогреватель.</p>
<p>Числовое ограничение, в котором учитываются розетки, есть в ПУЭ, п. 6.2.10, — для групповых линий освещения: как правило, не более 20 ламп на фазу, причём штепсельные розетки, подключённые к такой линии, входят в это число. Пункт называет лампы накаливания и разрядные лампы (ДРЛ, ДРИ, ДРИЗ, ДНаТ) и допускает исключения — например, для освещения лестниц, этажных коридоров и холлов. Эту проверку выполняет режим «Групповая линия освещения с розетками».</p>""",
example="""<p>Кухонная группа на автомате 16 А, 220 В: одновременно могут работать чайник 2000 Вт и микроволновая печь 1200 Вт. IB = 3200 / 220 ≈ <b>14,55 А</b> — условие IB ≤ In выполняется с запасом 320 Вт. Если добавить тостер 800 Вт, IB ≈ 18,18 А — номинал превышен, и такую нагрузку нужно разнести по разным группам или по времени.</p>""",
